<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Transaksi E-Voting';$eventId=(int)($_GET['event']??(active_event()['id']??0));$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$sql="SELECT vo.*,f.full_name finalist_name,f.category,r.name region_name FROM vote_orders vo JOIN finalists f ON f.id=vo.finalist_id JOIN regions r ON r.id=f.region_id WHERE vo.event_id=?";$params=[$eventId];if($status){$sql.=' AND vo.payment_status=?';$params[]=$status;}if($q){$sql.=' AND (vo.order_number LIKE ? OR vo.voter_name LIKE ? OR vo.voter_phone LIKE ? OR f.full_name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}$sql.=' ORDER BY vo.id DESC LIMIT 500';$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$events=db()->query('SELECT id,name,year FROM events ORDER BY year DESC')->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="admin-card p-4 mb-4"><form class="row g-3"><div class="col-lg-3"><label class="form-label">Event</label><select class="form-select" name="event"><?php foreach($events as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= $eventId==$ev['id']?'selected':'' ?>><?= e($ev['year'].' - '.$ev['name']) ?></option><?php endforeach;?></select></div><div class="col-lg-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">Semua Status</option><?php foreach(['CREATED','PENDING','PAID','FAILED','EXPIRED','CANCELED','REFUNDED','REVERSED'] as $v):?><option <?= $status===$v?'selected':'' ?>><?= $v ?></option><?php endforeach;?></select></div><div class="col-lg-4"><label class="form-label">Pencarian</label><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Nomor transaksi, pemilih, telepon, finalis"></div><div class="col-lg-2 d-flex align-items-end"><button class="btn btn-admin w-100">Filter</button></div></form></div>
<div class="admin-card overflow-hidden"><div class="p-4 d-flex justify-content-between align-items-center"><h5 class="mb-0">Hasil Transaksi <span class="text-secondary">(<?= count($rows) ?>)</span></h5><a class="btn btn-sm btn-outline-success" href="export-transactions.php?event=<?= $eventId ?>&status=<?= urlencode($status) ?>"><i class="bi bi-download me-2"></i>CSV</a></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Transaksi</th><th>Pemilih</th><th>Finalis</th><th>Nominal/Poin</th><th>Metode</th><th>Status</th><th>ID Xendit</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['order_number']) ?></strong><small class="d-block text-secondary"><?= indonesia_date($r['created_at'],true) ?></small></td><td><strong><?= e($r['voter_name']) ?></strong><small class="d-block text-secondary"><?= e(mask_phone(decrypt_value($r['voter_phone']))) ?></small></td><td><?= e($r['finalist_name']) ?><small class="d-block text-secondary"><?= e($r['category'].' • '.$r['region_name']) ?></small></td><td><?= rupiah($r['amount_snapshot']) ?><small class="d-block text-success fw-bold"><?= number_format((int)$r['total_points_snapshot'],0,',','.') ?> poin</small></td><td><?= e($r['payment_channel']?:'Xendit') ?></td><td><span class="badge <?= $r['payment_status']==='PAID'?'text-bg-success':(in_array($r['payment_status'],['CREATED','PENDING'],true)?'text-bg-warning':'text-bg-danger') ?>"><?= e($r['payment_status']) ?></span><?php if($r['paid_at']):?><small class="d-block text-secondary mt-1"><?= indonesia_date($r['paid_at'],true) ?></small><?php endif;?></td><td><small><?= e($r['xendit_payment_id']?:$r['xendit_session_id']?:'-') ?></small></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-5">Tidak ada transaksi sesuai filter.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/partials/footer.php';?>
